from pathlib import Path
import base64,gzip,hashlib,runpy,sys
here=Path(__file__).resolve().parent
data=gzip.decompress(base64.b64decode("",validate=True))
assert hashlib.sha256(data).hexdigest()=="9c7bc7f23c2892954dc0b574a7c5687d265a2efe664fa5803895bfa5a9255562"
target=here/"nbt.py"
if target.exists() and target.read_bytes()!=data: raise RuntimeError("Preserve edited source before replay")
target.write_bytes(data)

data=gzip.decompress(base64.b64decode("",validate=True))
assert hashlib.sha256(data).hexdigest()=="b06bd49a689c1d7eee5c06c75323a4ad01b1ffd9668bf7660856c8adf6a5e14b"
target=here/"build_hearthkeeper.py"
if target.exists() and target.read_bytes()!=data: raise RuntimeError("Preserve edited source before replay")
target.write_bytes(data)

sys.path.insert(0,str(here))
runpy.run_path(str(here/"build_hearthkeeper.py"),run_name="__main__")
out=here/"prefab-extension/hearthkeeper.nbt"
assert hashlib.sha256(gzip.decompress(out.read_bytes())).hexdigest()=="fe29f662fa665dc6133d16ef0f10bc84110dde554c9259cb23fae8250962d5bd"
(out.parent/"hearthkeeper.LICENSE.txt").write_bytes((here/"LICENSE.txt").read_bytes())
